const ic=(n,c='')=>`<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${P[n]}"/></svg>`;
/* a receipt slip */
const slip=(o={})=>`<figure class="slip ${o.cls||''}"${o.id?` id="${o.id}"`:''}><div class="slip-top"><b>Dealpin receipt</b><span class="ok">${o.tag||'Verified'}</span></div><p class="item"${o.id?` data-i`:''}>${o.item||'Blue kitenge dress'}</p><p class="amt" data-a>${o.amt||'UGX 85,000'}</p>${o.meta?`<p class="meta" data-m>${o.meta}</p>`:''}${o.trail===false?'':`<ul class="trail"><li><span>Buyer agreed</span><time>Tue 10:12</time></li><li><span>Pin and voice note shared</span><time>Tue 10:14</time></li><li><span>Rider arrived at pin</span><time>Tue 15:40</time></li><li><span>Handover code confirmed</span><time>Tue 15:43</time></li><li><span>Buyer tapped received</span><time>Tue 15:44</time></li></ul>`}<p class="code">Receipt code <b data-c>${o.code||'DP-7K4M-92QX'}</b></p><figcaption class="cap">${o.cap||'Example only'}</figcaption></figure>`;
/* a phone showing the buyer screen */
const phone=()=>`<div class="phone" aria-hidden="true"><div class="notch"></div><div class="scr"><div class="pbar"><b>Your deal</b><span>Agreed</span></div><div class="pcard"><b>Blue kitenge dress</b><span>UGX 85,000</span><small>Delivery by rider</small></div><div class="pbtn">${ic('pin')} Share my location</div><div class="pbtn alt">${ic('mic')} Record a voice note</div><div class="pbtn alt">${ic('receipt')} View receipt</div></div></div>`;
const head=(t,s)=>`<section class="phead"><div class="wrap"><h1>${t}</h1><p class="lead">${s}</p></div></section>`;
const cta=(t='Make your next sale one you can prove')=>`<section class="final"><div class="wrap"><h2>${t}</h2><div class="cta"><a class="btn pin" href="#/signin">Open Dealpin</a><a class="btn line" href="#/how">See how it works</a></div></div></section>`;

;
Pages.home={title:'Dealpin',desc:'Sell in chat. Prove every deal. Run your business. Send a deal link, get a yes, confirm the handover with a code, and keep a signed receipt.',
html:()=>`<section class="hero"><div class="wrap hero-in"><div class="hero-copy"><h1>Sell in chat. Prove every deal. Run your business.</h1><p class="lead">Sell on WhatsApp, Instagram or TikTok with a record both sides can trust. Send a link, get a yes, confirm the handover, and keep a signed receipt.</p><div class="cta"><a class="btn pin" href="#/signin">Open Dealpin</a><a class="btn line" href="app/#/verify">Verify a receipt</a></div><p class="fine">Free for every seller. Works in any browser and installs as an app. Your buyer needs no account.</p></div>
<div class="stage">${phone()}${slip({cls:'hero-slip'})}</div></div></section>
<section class="band"><div class="wrap band-in"><p>Chat sales move fast. Dealpin turns each one into a single record that the seller, the buyer and the rider all see in the same order, so every sale ends with proof.</p></div></section>
<section class="sec"><div class="wrap"><h2>From “how much?” to receipt in one link</h2>
<div class="flow">${[['link','Deal link','Seller sets item, price and terms'],['phone','Buyer agrees','Opens in any browser'],['pin','Pin and voice','Location, landmark, voice note'],['truck','Rider handover','Checks in, confirms the code'],['receipt','Receipt','Signed, shareable, verifiable']].map(x=>`<div class="fl">${ic(x[0])}<b>${x[1]}</b><span>${x[2]}</span></div>`).join('')}</div></div></section>
<section class="sec tint"><div class="wrap try"><div><h2>Make a sample deal</h2><p class="lead2">Type what you sell and watch the message and the receipt build. See the message and the receipt take shape as you type.</p>
<form id="demo" class="demo" novalidate><div class="f"><label for="d-item">What are you selling?</label><input id="d-item" maxlength="40" value="Leather handbag" autocomplete="off"></div><div class="f2"><div class="f"><label for="d-price">Price</label><input id="d-price" type="number" inputmode="decimal" min="0" step="any" value="120000"></div><div class="f"><label for="d-cur">Currency</label><select id="d-cur">${['UGX','KES','TZS','RWF','NGN','GHS','ZAR','USD','EUR','GBP','INR'].map(c=>`<option>${c}</option>`).join('')}</select></div></div><div class="f"><label for="d-del">Delivery</label><select id="d-del"><option>I deliver by rider</option><option>Buyer collects</option><option>Courier or bus parcel</option></select></div></form></div>
<div class="try-out" aria-live="polite"><div class="bubble"><span class="who">Your message in chat</span><p id="o-msg"></p></div>${slip({id:'o-slip',tag:'Sample',trail:false,meta:'',cap:'Sample receipt'})}</div></div></section>
<section class="sec"><div class="wrap"><h2>Explore what is inside</h2><div class="bento">
<a class="bt big" href="#/features">${ic('shield')}<h3>Proof you can verify</h3><p>Signed receipts, ratings, disputes and a public seller record.</p></a>
<a class="bt" href="#/tools">${ic('coins')}<h3>Business Autopilot</h3><p>Customers, pipeline, tasks, stock and purchasing. Free for every seller.</p></a>
<a class="bt" href="#/people">${ic('users')}<h3>Three views</h3><p>Seller, buyer and rider each see what they need.</p></a>
<a class="bt wide" href="#/trust">${ic('shield')}<h3>Trust Score, free for everyone</h3><p>A score out of 100 built from real completed deals, ratings and shipping speed. Verified sellers earn the badge at 70 and above.</p></a></div></div></section>${cta()}`,
init(){const code='DP-'+[...crypto.getRandomValues(new Uint8Array(8))].map((b,i)=>'ABCDEFGHJKMNPQRSTUVWXYZ23456789'[b%31]+(i===3?'-':'')).join('');
 const money=(v,c)=>{const n=parseFloat(v);if(!(n>0))return'Enter a price';try{return new Intl.NumberFormat(undefined,{style:'currency',currency:c,maximumFractionDigits:/^(UGX|RWF)$/.test(c)?0:2}).format(n)}catch{return c+' '+n}};
 const draw=()=>{const it=$('#d-item').value.trim()||'Your item',m=money($('#d-price').value,$('#d-cur').value),dl=$('#d-del').value,s=$('#o-slip');
  $('#o-msg').textContent=`Hi, here is your deal for ${it} (${m}): [your private deal link]`;$('[data-i]',s).textContent=it;$('[data-a]',s).textContent=m;$('[data-c]',s).textContent=code;s.insertAdjacentHTML('beforeend','');
  let me=$('[data-m]',s);if(!me){me=document.createElement('p');me.className='meta';me.dataset.m='';$('.amt',s).after(me)}me.textContent='Delivery: '+dl};
 $$('#demo input,#demo select').forEach(e=>{e.oninput=draw;e.onchange=draw});$('#demo').onsubmit=e=>e.preventDefault();draw()}};

;
Pages.how={title:'How it works · Dealpin',desc:'A deal link, a buyer who agrees, a pin and a voice note, a rider handover code, and a signed receipt.',
html:()=>head('How a Dealpin deal works','Five moments, one record. Everyone sees the same steps in the same order.')+`<section class="sec"><div class="wrap narrow"><ol class="tl">${[
['Seller makes the deal','Name the item, set the price and currency, pick how it is delivered, add terms and up to three photos. Dealpin creates private links for the buyer and the rider.'],
['Buyer agrees','They open the link in a browser. No app, no account. They read the item, price and terms, then agree in English, Luganda or Kiswahili.'],
['Buyer shares the spot','A location pin, a landmark and a short voice note. Location and microphone are used only when the buyer taps the button.'],
['Rider confirms the handover','The rider opens the delivery link, taps that they have arrived, and checks the handover code. Wrong codes are counted and limited.'],
['Buyer taps received','The deal becomes verified and a receipt with a code is created. Print it, save it as PDF, send it on WhatsApp, or verify it any time.']].map((s,i)=>`<li><span class="dot">${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></li>`).join('')}</ol></div></section>
<section class="sec tint"><div class="wrap"><h2>The life of a deal</h2><p class="lead2">Every deal moves through clear statuses.</p><div class="chips">${['Created','Agreed','Shipped','Received','Disputed','Cancelled','Resolved'].map((s,i)=>`<span class="chip${i<4?' main':''}">${s}</span>`).join('')}</div><p class="lead2">If a buyer reports a problem the deal shows Disputed with their description and photo. The seller replies and marks it Resolved. Dealpin keeps the full record so both sides see the same facts.</p></div></section>${cta()}`};

;
Pages.features={title:'Features · Dealpin',desc:'Deal links, handover codes, signed receipts, Trust Score, Daily Command, Business Autopilot, stock and purchasing. Free for every seller.',
html:()=>head('Everything a chat seller needs','Proof first. Around it, the storefront, the daily routine and the back office of a growing business.')+`<section class="sec"><div class="wrap fgroups">${[
['Deals and proof','shield',['Deal links|Separate private links for seller, buyer and rider.','Buyers need no account|Agree, share a pin, landmark and voice note, record payment, confirm receipt.','Handover code|Riders confirm with a code, with limited wrong tries.','Signed receipts|Print, save as PDF, save as an image or send on WhatsApp.','Verify any receipt|Enter a code and check it at any time.','Ratings and disputes|Photo and description, reply, mark resolved.','Trust Score|Out of 100 from real deals. Verified at 70 and above.']],
['Run the business daily','users',['Daily Command|Start each day with what needs attention, ranked by urgency.','Universal Inbox|Everything waiting for you in one place, with unread and done states.','Business Autopilot|Customers, pipeline, tasks, suppliers, expenses, staff and branches.','Relationship Memory|Each customer’s deals, recorded value, open work and timeline.','Stock and purchasing|Stock ledger, purchase orders, reservations and valuation estimates.','Alerts|Optional alerts when a deal changes, on devices you allow.']],
['Products and storefront','box',['Catalogue|Published, draft and paused, with search, categories and up to five photos.','Explore|Live listings with filters, sorting and paging.','Product pages|One shareable link per product.','Purchase requests|Quantity and offer; accept, decline or counter.','Request to deal|One tap turns an accepted request into a deal.']],
['Built for where you sell','globe',['Free for every seller|Every feature, with no subscriptions and no paid tiers.','Any country and currency|Each deal keeps its own currency.','Buyer languages|English, Luganda and Kiswahili. Seller screens are partly translated.','Install and offline|Use it without a connection; answers send when you are back online.','Passwordless sign-in|Google, email code or SMS code.','Light and dark|Follows your phone.','Your data is yours|Download it or delete your account any time.']]
].map(g=>`<div class="fg">${ic(g[1],'big')}<h3>${g[0]}</h3><ul>${g[2].map(x=>{x=x.split('|');return`<li><b>${x[0]}.</b> ${x[1]}</li>`}).join('')}</ul></div>`).join('')}</div></section>${cta()}`};

;
Pages.tools={title:'Seller tools · Dealpin',desc:'Business Autopilot, deliveries and riders, rider settlements, ledger, invoices, stock and purchasing. Free for every seller.',
html:()=>head('Seller tools','Everything a chat business runs on, in one app, free for every seller.')+`<section class="sec"><div class="wrap rows">${[
['users','Business Autopilot','Customers, opportunities, tasks, suppliers, expenses, staff and branches, with a Daily Command that ranks what needs attention first.'],
['truck','Deliveries and riders','Pickups and drop-offs with fees, cash on delivery, a proof photo, a map pin and a server-checked handover code.'],
['coins','Rider settlements','Flat or percentage pay, totalled for each rider so end-of-day sums are exact.'],
['book','Ledger','Who owes you and who you owe, with part payments, due dates and a WhatsApp reminder.'],
['doc','Invoices','Line items, tax, discounts and payments. Make an invoice straight from a deal.'],
['box','Stock and purchasing','A stock ledger that records every movement, purchase orders that update stock when received, and reservations that turn into sales.'],
['users','Group orders','Collect several buyers into one order and keep it tidy.']].map((t,i)=>`<article class="row${i%2?' alt':''}"><div class="rv">${ic(t[0],'huge')}</div><div><h3>${t[1]}</h3><p>${t[2]}</p></div></article>`).join('')}</div></section>${cta()}`};

;
Pages.people={title:'Who it is for · Dealpin',desc:'One deal, three views: seller, buyer and rider.',
html:()=>head('One deal, three views','Each person sees the parts of the deal they need, and nothing more.')+`<section class="sec"><div class="wrap"><div class="tabs" role="tablist" aria-label="Choose a role">${['seller','buyer','rider'].map((r,i)=>`<button role="tab" id="t-${r}" aria-selected="${!i}" aria-controls="p-${r}" type="button"${i?' tabindex="-1"':''}>${r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div>
<div class="roleview"><div><div class="panel" id="p-seller" role="tabpanel" aria-labelledby="t-seller"><h3>Seller</h3><p><a href="#/sellers">Full guide for sellers</a>. Make the deal, send the link and watch it move from created to received. Remind a buyer on WhatsApp, mark a payment received and open a delivery. Every verified deal builds the public record new buyers check before they trust you.</p></div>
<div class="panel" id="p-buyer" role="tabpanel" aria-labelledby="t-buyer" hidden><h3>Buyer</h3><p>Open a link, read the item, price and terms, and agree. Share where to deliver, record your payment, give the rider a code, tap received and get a receipt. If something is wrong, report it with a photo from the same page.</p></div>
<div class="panel" id="p-rider" role="tabpanel" aria-labelledby="t-rider" hidden><h3>Rider</h3><p>Get a delivery link with the pin, landmark and a number to call. Tap arrived, ask for the code and confirm the handover. Your steps are time-stamped, so nobody argues about when you got there.</p></div></div>${phone()}</div></div></section>${cta()}`,
init(){const t=$$('[role=tab]'),pick=x=>{t.forEach(y=>{const on=y===x;y.setAttribute('aria-selected',on);y.tabIndex=on?0:-1;$('#'+y.getAttribute('aria-controls')).hidden=!on});x.focus()};
 t.forEach((x,i)=>{x.onclick=()=>pick(x);x.onkeydown=e=>{const n=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;if(n){e.preventDefault();pick(t[(i+n+3)%3])}}})}};

;
Pages.trust={title:'Trust and security · Dealpin',desc:'Trust Score out of 100, free for every seller. Private receipts, server-checked deal changes and strict security headers.',
html:()=>head('Trust you can see','Every deal leaves a record both sides can check, and every seller can earn a public Trust Score.')+`<section class="sec"><div class="wrap trust"><div><h2>Trust Score, free for everyone</h2><p>Your Trust Score is out of 100 and is built from real completed deals: completed deals earn 25 points, buyer ratings 30, no disputes 25, and shipping within 2 days 20. A score appears once you complete 5 deals, and 70 or more earns the Verified badge.</p></div><div><h2>Your money stays in your hands</h2><p>Buyers and sellers pay each other directly by mobile money, bank transfer, card or cash on delivery. Dealpin records what was agreed, delivered and confirmed, so both sides keep full control of their money.</p></div></div></section>
<section class="sec tint"><div class="wrap narrow"><h2>Built to protect every record</h2><ul class="checks">${['Receipts show only what the buyer needs. A buyer’s phone number and location never appear on a receipt.','Every deal change runs through secure server functions, with row-level security and rate limits.','A strict Content Security Policy protects every page from injected scripts.','Secret keys stay on the server and never ship inside the app.','Location and microphone are used only when you tap the button that asks.','Buyer and rider links are private: share each one only with the person it is for.','Download your data or delete your account at any time.'].map(x=>`<li>${x}</li>`).join('')}</ul></div></section>
<section class="sec"><div class="wrap narrow"><p class="lead2">Read the full <a href="app/privacy.html">privacy policy</a> and <a href="app/terms.html">terms of service</a>, or write to <a href="mailto:dealpin.net@gmail.com">dealpin.net@gmail.com</a>.</p></div></section>${cta()}`};

;
Pages.faq={title:'FAQ · Dealpin',desc:'Answers about buyers, money, disputes, currencies, languages, offline use and data.',
html:()=>head('Questions','Short answers, plainly.')+`<section class="sec"><div class="wrap narrow">${[
['Does my buyer need to install anything?','No. They open your link in any phone or computer browser and do not create an account.'],
['Does Dealpin hold the money?','No. Payment happens between you and the buyer, outside Dealpin. Dealpin records what both sides report.'],
['What happens if there is a dispute?','The buyer reports a problem with a description and a photo. You reply and mark it resolved. Dealpin keeps the full order of events, so both sides can see exactly what happened.'],
['Can I use it in my country and currency?','Yes. Pick your country and currency in Settings. Each deal keeps its own currency.'],
['Which languages are supported?','Buyer screens: English, Luganda and Kiswahili. Seller screens are partly translated while native speakers review the wording.'],
['Can I use it offline?','You can install Dealpin and open it without a connection. A buyer’s answer saved offline is sent when the connection returns.'],
['Who can see my data?','The seller, the buyer and the rider each see only the parts of a deal they need. See the <a href="app/privacy.html">privacy policy</a>.'],
['How do I check a receipt I was sent?','Open <a href="app/#/verify">Verify a receipt</a> and enter the code.']].map(q=>`<details><summary>${q[0]}</summary><p>${q[1]}</p></details>`).join('')}</div></section>${cta('Still have a question?')}`};

;
Pages.about={title:'About · Dealpin',desc:'Our mission: sell in chat, prove every deal, run your business. Why Dealpin exists and what it stands for.',
html:()=>head('Our mission','Millions of people run real businesses from a chat window. They deserve records as good as a shop with a till.')+`<section class="sec"><div class="wrap narrow"><h2>Why Dealpin exists</h2><p class="lead2">A sale agreed in chat is fast. Dealpin gives it a shared record: what was agreed, where it goes, who confirmed what and when, so both sides always have the same facts.</p>
<h2>What we stand for</h2><div class="vals">${[['Clear and trusted','Every deal leaves one record both sides can see, and every seller can earn a Trust Score from real completed deals.'],['Built for how people sell','Mobile first, no account for buyers, any country and currency, and buyer screens in English, Luganda and Kiswahili.'],['Private by default','Each person sees only their part of a deal. Receipts never show a buyer’s phone number or location.'],['Free for every seller','Every feature is free, with no subscriptions and no paid tiers.']].map(v=>`<div class="val"><h3>${v[0]}</h3><p>${v[1]}</p></div>`).join('')}</div></div></section>${cta()}`};

;
Pages.install={title:'Get the app · Dealpin',desc:'Open Dealpin in your browser or install it on Android, iPhone or a computer. No app store needed.',
html:()=>head('Get Dealpin','Open it in any browser, or install it so it sits on your home screen and opens offline. No app store.')+`<section class="sec"><div class="wrap"><div class="cta"><a class="btn pin" href="#/signin">Open Dealpin now</a><a class="btn" href="app/#/verify">Verify a receipt</a></div>
<h2>Install it</h2><div class="plat">${[['Android','Chrome',['Open Dealpin in Chrome.','Tap the menu (three dots).','Tap Install app or Add to Home screen.']],['iPhone and iPad','Safari',['Open Dealpin in Safari.','Tap the Share button.','Tap Add to Home Screen, then Add.']],['Computer','Chrome or Edge',['Open Dealpin.','Click the install icon in the address bar.','Click Install.']]].map(p=>`<div class="panel"><h3>${p[0]}</h3><small>${p[1]}</small><ol>${p[2].map(x=>`<li>${x}</li>`).join('')}</ol></div>`).join('')}</div>
<p class="lead2">Buyers and riders just open the link you send. Nothing to install. They just open the link you send. Install steps can differ slightly between browser versions.</p></div></section>${cta()}`};

;
Pages.contact={title:'Contact · Dealpin',desc:'Questions, feedback or partnership ideas? Write to the Dealpin team.',
html:()=>head('Talk to us','Questions, feedback, a problem with a deal or an idea to work together. We read everything.')+`<section class="sec"><div class="wrap try"><form id="cf" class="demo" novalidate><div class="f"><label for="c-n">Your name</label><input id="c-n" maxlength="60" autocomplete="name"></div><div class="f"><label for="c-t">Topic</label><select id="c-t"><option>Question</option><option>Problem with a deal</option><option>Feedback or idea</option><option>Partnership</option></select></div><div class="f"><label for="c-m">Message</label><textarea id="c-m" maxlength="1500"></textarea></div><button class="btn pin" type="submit">Write the email</button><p class="msg" id="c-s" role="status"></p></form>
<div><h2>Email us</h2><p class="lead2">The button opens your email app with the message ready to send, so nothing passes through this website. You can also write directly to <a href="mailto:dealpin.net@gmail.com">dealpin.net@gmail.com</a>.</p><p class="lead2">For a problem with a specific deal, include the receipt code. Keep private buyer and rider links to yourself. Send us the receipt code instead.</p></div></div></section>`,
init(){$('#cf').onsubmit=e=>{e.preventDefault();const m=$('#c-m').value.trim(),s=$('#c-s');if(!m){s.className='msg err';s.textContent='Write your message first.';return}
 s.className='msg';s.textContent='Opening your email app…';location.href='mailto:dealpin.net@gmail.com?subject='+encodeURIComponent('Dealpin: '+$('#c-t').value)+'&body='+encodeURIComponent(m+($('#c-n').value.trim()?'\n\n'+$('#c-n').value.trim():''))}}};

;
/* Website sign-in: Google or email code. Writes the same session the app reads (same origin), then opens the app. */
Pages.signin={title:'Sign in · Dealpin',desc:'Sign in to Dealpin with Google or an email code.',
html:()=>`<section class="auth-page"><div class="authcard"><h1 class="auth-h">Sign in to Dealpin</h1><p class="lead2" id="a-sub">Use Google or get a code by email. New here? Signing in creates your account.</p>
<div id="a-main"><button class="gbtn" id="a-g" type="button"><svg viewBox="0 0 48 48" width="20" height="20" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9 3.5l6.7-6.7C35.6 2.4 30.2 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.8 6.1C12.3 13.6 17.7 9.5 24 9.5z"/><path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.6 5.9c4.5-4.2 7-10.3 7-17.6z"/><path fill="#FBBC05" d="M10.4 28.7A14.5 14.5 0 0 1 9.5 24c0-1.6.3-3.2.9-4.7l-7.8-6.1A24 24 0 0 0 0 24c0 3.9.9 7.5 2.6 10.8z"/><path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.6-5.9c-2.1 1.4-4.9 2.3-8.3 2.3-6.3 0-11.7-4.1-13.6-9.8l-7.8 6.1C6.5 42.6 14.6 48 24 48z"/></svg>Continue with Google</button>
<p class="or"><span>or</span></p>
<form id="a-e" class="demo" novalidate><div class="f"><label for="a-mail">Email address</label><input id="a-mail" type="email" inputmode="email" autocomplete="email" maxlength="120" placeholder="you@example.com"></div><button class="btn pin" type="submit">Email me a code</button></form>
<form id="a-c" class="demo" novalidate hidden><div class="f"><label for="a-code">Code from your email</label><input id="a-code" inputmode="numeric" autocomplete="one-time-code" maxlength="8" placeholder="123456"></div><button class="btn pin" type="submit">Sign in</button><div class="alt"><button class="lnk" id="a-re" type="button">Send a new code</button><button class="lnk" id="a-ch" type="button">Use a different email</button></div></form>
<p class="msg" id="a-s" role="status" aria-live="polite"></p></div>
<p class="fine2">By continuing you agree to the <a href="app/terms.html">Terms</a> and <a href="app/privacy.html">Privacy policy</a>. Buyers and riders just open the link they are sent. No account needed.</p></div></section>`,
maint(){const C=window.DEALPIN||{};if(C.mode!=='supabase'||!C.url||!C.anonKey)return;
  fetch(C.url+'/rest/v1/app_settings?select=message,maintenance&id=eq.1',{headers:{apikey:C.anonKey,Accept:'application/json'},cache:'no-store'})
  .then(r=>r.ok?r.json():null).then(j=>{const st=Array.isArray(j)?j[0]:null;if(!st||!st.maintenance)return;
    const card=document.querySelector('.authcard');if(!card)return;
    const h=document.createElement('h1');h.className='auth-h';h.textContent='Back soon';
    const p=document.createElement('p');p.className='lead2';p.textContent=st.message||'Dealpin is being updated. Please try again shortly.';
    card.replaceChildren(h,p);}).catch(()=>{});},
init(){this.maint();
 const C=window.DEALPIN||{},K='dealpin.session',s=$('#a-s'),say=(t,e)=>{s.className='msg'+(e?' err':'');s.textContent=t};
 const ok=()=>{try{const u=new URL(C.url);return C.mode==='supabase'&&u.protocol==='https:'&&!!C.anonKey}catch{return false}};
 const goApp=()=>location.replace('app/');
 if(!ok())return goApp();
 try{if(JSON.parse(localStorage.getItem(K)||'null')?.refresh_token)return goApp()}catch{}
 const post=async(p,b)=>{let r;try{r=await fetch(C.url+p,{method:'POST',headers:{apikey:C.anonKey,'Content-Type':'application/json'},body:JSON.stringify(b)})}catch{throw new Error('No connection. Check your internet and try again.')}
  const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(r.status===429?'Too many tries. Wait a minute and try again.':j.error_code==='otp_expired'?'That code has expired. Ask for a new one.':j.msg||j.message||j.error_description||'Could not sign in. Try again.');return j};
 const b64=a=>btoa(String.fromCharCode(...new Uint8Array(a))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
 const pair=async()=>{const v=b64(crypto.getRandomValues(new Uint8Array(48))),ch=b64(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v)));
  try{localStorage.setItem('dealpin.pkce',JSON.stringify({v,t:Date.now()}))}catch{throw new Error('This browser blocks sign-in storage. Turn off private mode and try again.')}return ch};
 const back=location.origin+'/app/';let mail='',cool=0;
 const lock=(b,on)=>{b.disabled=on};
 $('#a-g').onclick=async e=>{lock(e.currentTarget,1);try{const ch=await pair();location.assign(C.url+'/auth/v1/authorize?'+new URLSearchParams({provider:'google',redirect_to:back,code_challenge:ch,code_challenge_method:'s256'}))}catch(x){say(x.message,1);lock(e.currentTarget,0)}};
 const send=async()=>{const ch=await pair();await post('/auth/v1/otp?redirect_to='+encodeURIComponent(back),{email:mail,create_user:true,code_challenge:ch,code_challenge_method:'s256'});
  $('#a-e').hidden=true;$('#a-c').hidden=false;$('#a-sub').textContent='We sent a code to '+mail+'. Enter it below.';say('Code sent. Check your inbox and spam.');$('#a-code').focus();cool=Date.now()+30000};
 $('#a-e').onsubmit=async e=>{e.preventDefault();mail=$('#a-mail').value.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(mail))return say('Enter a valid email address.',1);
  const b=$('#a-e button');lock(b,1);say('Sending…');try{await send()}catch(x){say(x.message,1)}lock(b,0)};
 $('#a-c').onsubmit=async e=>{e.preventDefault();const t=$('#a-code').value.trim();if(!/^\d{4,8}$/.test(t))return say('Enter the code from the email.',1);
  const b=$('#a-c button');lock(b,1);say('Checking…');try{const j=await post('/auth/v1/verify',{type:'email',email:mail,token:t});
   if(!j.access_token)throw new Error('Sign-in did not complete. Try again.');
   localStorage.setItem(K,JSON.stringify({access_token:j.access_token,refresh_token:j.refresh_token,expires_at:Date.now()+(j.expires_in||3600)*1000,user:{id:j.user&&j.user.id,name:(j.user&&j.user.user_metadata&&(j.user.user_metadata.full_name||j.user.user_metadata.name))||'',email:(j.user&&j.user.email)||mail}}));say('Signed in. Opening Dealpin…');goApp()}
  catch(x){say(x.message,1);lock(b,0)}};
 $('#a-re').onclick=async()=>{if(Date.now()<cool)return say('Wait a few seconds before asking again.',1);say('Sending…');try{await send()}catch(x){say(x.message,1)}};
 $('#a-ch').onclick=()=>{$('#a-c').hidden=true;$('#a-e').hidden=false;$('#a-sub').textContent='Use Google or get a code by email. New here? Signing in creates your account.';say('');$('#a-mail').focus()};
}};

;
Pages.sellers={title:'For sellers · Dealpin',desc:'Create a deal link in minutes, send it on WhatsApp, Instagram or TikTok, and keep a receipt for every sale.',
html:()=>head('For sellers','Sell from your phone, keep the record, and answer “did you get it?” with proof.')+`<section class="sec"><div class="wrap narrow"><h2>Start a sale</h2><ol class="tl">${[
['Create the deal','Name the item, set the price and currency, choose delivery or pickup, add terms and up to three photos.'],
['Send the link','Share it in your chat. The buyer opens it in a browser and does not need an account.'],
['Follow it','Watch the status move from created to agreed, shipped and received. Remind the buyer from the deal when needed.'],
['Keep the receipt','When the buyer confirms receipt, the deal is verified and a receipt with a code is created. Print it, save it as PDF or send it on WhatsApp.']].map((s,i)=>`<li><span class="dot">${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></li>`).join('')}</ol></div></section>
<section class="sec tint"><div class="wrap narrow"><h2>Beyond one deal</h2><div class="bento">
<a class="bt" href="#/tools"><h3>Seller tools</h3><p>Deliveries, ledger, invoices, stock and group orders.</p></a>
<a class="bt" href="#/explore"><h3>Explore and products</h3><p>Publish products that anyone can browse, and turn buyer interest into a deal.</p></a>
<a class="bt" href="#/trust"><h3>Your public record</h3><p>Verified deals and ratings build a seller record that buyers can check.</p></a>
<a class="bt" href="#/faq"><h3>Questions</h3><p>Money, disputes, currencies and languages, answered plainly.</p></a></div>
<p class="fine">Payment happens between you and the buyer, outside Dealpin. Dealpin records what both sides report.</p></div></section>${cta('Create your first deal link')}`};

;
Pages.buyers={title:'For buyers · Dealpin',desc:'Open a seller’s link, agree to the deal, confirm delivery and keep a receipt. No account needed.',
html:()=>head('For buyers','Open the link, agree, and keep proof of what you paid for and received.')+`<section class="sec"><div class="wrap narrow"><h2>What you do</h2><ol class="tl">${[
['Open the link','Tap the link the seller sent. It opens in any phone or computer browser, with no app to install and no account to create.'],
['Read and agree','Check the item, price, currency and terms, then agree. You can read Dealpin in English, Luganda or Kiswahili.'],
['Share the delivery spot (optional)','Tap the button to share a location pin, a landmark and a short voice note. Location and microphone are used only when you tap.'],
['Confirm receipt','When the item arrives, tap “I received it”. The deal becomes verified and you get a receipt with a code.'],
['Report a problem','If something is wrong, report it with a description and a photo. The seller replies, and the record keeps the order of events.']].map((s,i)=>`<li><span class="dot">${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></li>`).join('')}</ol></div></section>
<section class="sec tint"><div class="wrap narrow"><h2>Check a receipt</h2><p class="lead2">Anyone can verify a receipt with its code, at <a href="app/#/verify">Verify a receipt</a>. Pay the seller directly by the method you agree, and keep the receipt Dealpin gives you.</p></div></section>${cta('Open a deal link you were sent')}`};

;
Pages.riders={title:'For riders · Dealpin',desc:'Get a delivery link with the pin and landmark, confirm arrival and complete the handover with a code.',
html:()=>head('For riders','A delivery link, a clear pin and a timed handover. No account needed.')+`<section class="sec"><div class="wrap narrow"><h2>A delivery, step by step</h2><ol class="tl">${[
['Open the delivery link','The seller gives you a private link for this delivery. It shows the pin, the landmark and a number to call. Only what the delivery needs is shown here.'],
['Tap arrived','Your arrival is time-stamped in the record.'],
['Complete the handover','Ask the buyer for the handover code, enter it, and confirm. Wrong codes are counted and limited, so a guess will not work.']].map((s,i)=>`<li><span class="dot">${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></li>`).join('')}</ol></div></section>
<section class="sec tint"><div class="wrap narrow"><h2>Why this protects you</h2><p class="lead2">Your steps are time-stamped, so the timing of a delivery is recorded for everyone. If a buyer disputes a delivery, the record shows what happened and when.</p></div></section>${cta('Have a delivery link? Open it now')}`};

;
Pages.explore={title:'Explore · Dealpin',desc:'Browse products that sellers have published on Dealpin, and send a purchase request.',
html:()=>head('Explore','Products sellers have chosen to publish, open to anyone to browse.')+`<section class="sec"><div class="wrap narrow"><div class="bento">
<a class="bt" href="app/#/explore"><h3>Browse products</h3><p>See published products, prices and seller names in the Explore tab of the app.</p></a>
<a class="bt" href="#/sellers"><h3>Publish a product</h3><p>Sellers add a product with photos, a price and a description. Set it to published when it is ready.</p></a>
<a class="bt" href="#/buyers"><h3>Send a request</h3><p>Choose a quantity, offer a price if you want, and send your name and phone. The seller replies, and an accepted request becomes a deal.</p></a>
<a class="bt" href="#/trust"><h3>Share</h3><p>Each product has its own page. Share it on WhatsApp or copy the link.</p></a></div>
<p class="fine">Product listings are shown as the seller published them. Check the price, currency and seller before you pay anyone.</p></div></section>${cta('Publish your first product')}`};

