Pages.legal={title:'Terms and privacy · Dealpin',desc:'The terms of use and the privacy policy for Dealpin.',
html:()=>head('Terms and privacy','The full terms and privacy policy are in the app. Here is where to find them and how to reach us.')+`<section class="sec"><div class="wrap narrow"><div class="bento">
<a class="bt" href="app/terms.html"><h3>Terms of use</h3><p>The rules for sellers, buyers and riders using Dealpin.</p></a>
<a class="bt" href="app/privacy.html"><h3>Privacy policy</h3><p>What data is kept, who can see it, and how long it is kept.</p></a>
<a class="bt" href="#/contact"><h3>Contact us</h3><p>Questions about your data or your account.</p></a></div></div></section>${cta()}`};

